-- Tests are done panel-wise. Each panel type (Control Desk, RIO Panel, LT Distribution Board...)
-- has its own list of tests in a library kept by the design team (permission "panel_tests",
-- given to the Jr Designer). On an order, each panel (from the BOM / Production) gets the tests
-- of its panel type; the Testing page fills in OK / Not OK / N.A. and a reading per test.
--
-- * panel_test_templates: the library. `aliases` are other names the same panel goes by in a
--   BOM ("Test Bench" = "Control Desk"). `tests` is a list of {group, title}.
-- * test_items.panel_id: which panel of the order a test belongs to (NULL = older order-wide
--   tests from the quotation).
-- * test_items.status gains 'na' (not applicable).

CREATE TABLE public.panel_test_templates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL CHECK (trim(name) <> ''),
  aliases text[] NOT NULL DEFAULT '{}',
  tests jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(tests) = 'array'),
  display_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX panel_test_templates_name_idx ON public.panel_test_templates (lower(trim(name)));
CREATE TRIGGER set_panel_test_templates_updated_at BEFORE UPDATE ON public.panel_test_templates
  FOR EACH ROW EXECUTE FUNCTION public.set_project_stage_updated_at();

GRANT SELECT, INSERT, UPDATE, DELETE ON public.panel_test_templates TO authenticated;
GRANT ALL ON public.panel_test_templates TO service_role;
REVOKE ALL ON public.panel_test_templates FROM anon;

ALTER TABLE public.panel_test_templates ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read" ON public.panel_test_templates FOR SELECT TO authenticated USING (true);
CREATE POLICY "add" ON public.panel_test_templates FOR INSERT TO authenticated
  WITH CHECK (public.can_edit('{panel_tests}'));
CREATE POLICY "change" ON public.panel_test_templates FOR UPDATE TO authenticated
  USING (public.can_edit('{panel_tests}')) WITH CHECK (public.can_edit('{panel_tests}'));
CREATE POLICY "remove" ON public.panel_test_templates FOR DELETE TO authenticated
  USING (public.can_edit('{panel_tests}'));

