-- ---------- Tests per panel ----------
ALTER TABLE public.test_items
  ADD COLUMN panel_id uuid REFERENCES public.production_panels (id) ON DELETE CASCADE;
CREATE INDEX test_items_panel_idx ON public.test_items (panel_id);

-- The old "one test key per order" rule and status list go, whatever they were named.
DO $$
DECLARE
  c record;
BEGIN
  FOR c IN
    SELECT conname FROM pg_constraint
    WHERE conrelid = 'public.test_items'::regclass
      AND (contype = 'u' OR (contype = 'c' AND pg_get_constraintdef(oid) LIKE '%status%'))
  LOOP
    EXECUTE format('ALTER TABLE public.test_items DROP CONSTRAINT %I', c.conname);
  END LOOP;
END;
$$;

ALTER TABLE public.test_items
  ADD CONSTRAINT test_items_order_panel_key UNIQUE NULLS NOT DISTINCT (inward_order_id, panel_id, test_key);
ALTER TABLE public.test_items ADD CONSTRAINT test_items_status_check
  CHECK (status IN ('pending', 'in progress', 'passed', 'failed', 'retest', 'na'));

SELECT public.audit_enable('public.panel_test_templates');
